def goodPaths(vals, edges):
    n = len(vals)
    parent = list(range(n))
    cnt = [1] * n          # how many nodes in the component hold its maximum value
    top = vals[:]          # maximum value of the component

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = n
    for a, b in sorted(edges, key=lambda e: max(vals[e[0]], vals[e[1]])):
        ra, rb = find(a), find(b)
        if top[ra] > top[rb]:
            parent[rb] = ra
        elif top[ra] < top[rb]:
            parent[ra] = rb
        else:
            total += cnt[ra] * cnt[rb]
            parent[rb] = ra
            cnt[ra] += cnt[rb]
    return total
